//	Wartość  | Opis
//	-----------+------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	InProgress | Sesja aktywna.
//	Succeeded  | Sesja przetworzona poprawnie. W trakcie przetwarzania sesji nie wystąpiły żadne błędy, ale część faktur nadal mogła zostać odrzucona.
//	Failed     | Sesja nie przetworzona z powodu błędów. Na etapie rozpoczynania lub kończenia sesji wystąpiły błędy, które nie pozwoliły na jej poprawne przetworzenie.
//	Cancelled  | Sesja anulowania. Został przekroczony czas na wysyłkę w sesji wsadowej, lub nie przesłano żadnych faktur w sesji interaktywnej.
//
// Ref: #/components/schemas/CommonSessionStatus
type CommonSessionStatus string

const (
	CommonSessionStatusInProgress CommonSessionStatus = "InProgress"
	CommonSessionStatusSucceeded  CommonSessionStatus = "Succeeded"
	CommonSessionStatusFailed     CommonSessionStatus = "Failed"
	CommonSessionStatusCancelled  CommonSessionStatus = "Cancelled"
)

// AllValues returns all CommonSessionStatus values.
func (CommonSessionStatus) AllValues() []CommonSessionStatus {
	return []CommonSessionStatus{
		CommonSessionStatusInProgress,
		CommonSessionStatusSucceeded,
		CommonSessionStatusFailed,
		CommonSessionStatusCancelled,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s CommonSessionStatus) MarshalText() ([]byte, error) {
	switch s {
	case CommonSessionStatusInProgress:
		return []byte(s), nil
	case CommonSessionStatusSucceeded:
		return []byte(s), nil
	case CommonSessionStatusFailed:
		return []byte(s), nil
	case CommonSessionStatusCancelled:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *CommonSessionStatus) UnmarshalText(data []byte) error {
	switch CommonSessionStatus(data) {
	case CommonSessionStatusInProgress:
		*s = CommonSessionStatusInProgress
		return nil
	case CommonSessionStatusSucceeded:
		*s = CommonSessionStatusSucceeded
		return nil
	case CommonSessionStatusFailed:
		*s = CommonSessionStatusFailed
		return nil
	case CommonSessionStatusCancelled:
		*s = CommonSessionStatusCancelled
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

